INSERT INTO `products` (`id`, `name`, `brand`, `type`, `capacity`, `price`, `stock`, `image`, `description`, `features`, `created_at`, `updated_at`, `image_alt`, `image_mime`, `slug`) VALUES
('ARR-KIOS05', 'Ariston KIOS05', 'ARISTON', 'AC Split', '1/2 PK', 2100000.00, 10, , 'AC Split Ariston KIOS05 kapasitas 1/2 PK cocok untuk ruangan kecil hingga 10 m². Dilengkapi teknologi pendingin efisien dengan kompresor berkualitas tinggi untuk kesejukan optimal. Fitur auto-restart melindungi unit saat terjadi pemadaman listrik mendadak. Desain ramping dan modern cocok untuk berbagai interior ruangan. Harga belum termasuk sparepart tambahan. Pembelian 1 unit gratis pipa sepanjang 1 meter.', NULL, '2026-05-14 13:26:18', '2026-05-15 11:55:29', NULL, 'image/webp', NULL),
('ARR-KIOS09', 'Ariston KIOS09', 'ARISTON', 'AC Split', '1 PK', 2550000.00, 10, , 'AC Split Ariston KIOS09 kapasitas 1 PK cocok untuk ruangan sedang hingga 18 m². Dilengkapi teknologi pendingin efisien dengan kompresor berkualitas tinggi untuk kesejukan optimal. Fitur auto-restart melindungi unit saat terjadi pemadaman listrik mendadak. Desain ramping dan modern cocok untuk berbagai interior ruangan. Harga belum termasuk sparepart tambahan. Pembelian 1 unit gratis pipa sepanjang 1 meter.', NULL, '2026-05-14 13:26:18', '2026-05-15 11:55:44', NULL, 'image/webp', NULL),
('ARR-KIOS12', 'Ariston KIOS12', 'ARISTON', 'AC Split', '1.5 PK', 3550000.00, 10, , 'AC Split Ariston KIOS12 kapasitas 1.5 PK cocok untuk ruangan sedang hingga 24 m². Dilengkapi teknologi pendingin efisien dengan kompresor berkualitas tinggi untuk kesejukan optimal. Fitur auto-restart melindungi unit saat terjadi pemadaman listrik mendadak. Desain ramping dan modern cocok untuk berbagai interior ruangan. Harga belum termasuk sparepart tambahan. Pembelian 1 unit gratis pipa sepanjang 1 meter.', NULL, '2026-05-14 13:26:18', '2026-05-15 11:55:56', NULL, 'image/webp', NULL);
INSERT INTO `products` (`id`, `name`, `brand`, `type`, `capacity`, `price`, `stock`, `image`, `description`, `features`, `created_at`, `updated_at`, `image_alt`, `image_mime`, `slug`) VALUES
('CHG-05NVS4', 'Changhong 05NVS4', 'CHANGHONG', 'AC Split', '1/2 PK', 2450000.00, 10, , 'AC Split Changhong 05NVS4 kapasitas 1/2 PK. Seri terbaru dengan teknologi inverter untuk penghematan energi lebih optimal. Pendinginan cepat dan stabil dengan tingkat kebisingan rendah untuk kenyamanan maksimal. Harga belum termasuk sparepart tambahan. Pembelian 1 unit gratis pipa sepanjang 1 meter.', NULL, '2026-05-14 13:26:18', '2026-05-15 11:56:10', NULL, 'image/webp', NULL);
