--
-- Structure for view `v_dashboard_stats`
--
DROP TABLE IF EXISTS `v_dashboard_stats`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_dashboard_stats`  AS SELECT count(0) AS `totalOrders`, coalesce(sum((case when (`orders`.`payment_status` = 'settlement') then `orders`.`total_price` else 0 end)),0) AS `totalRevenue`, count((case when (`orders`.`order_status` = 'pending') then 1 end)) AS `pendingOrders`, (select count(0) from `products`) AS `totalProducts` FROM `orders` ;

-- --------------------------------------------------------

--
-- Structure for view `v_orders_admin`
--
DROP TABLE IF EXISTS `v_orders_admin`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_orders_admin`  AS SELECT `o`.`id` AS `id`, `o`.`customer_name` AS `customer_name`, `o`.`phone` AS `phone`, `o`.`address` AS `address`, `o`.`payment_method` AS `payment_method`, `o`.`payment_status` AS `payment_status`, `o`.`order_status` AS `status`, `o`.`total_price` AS `total_price`, `o`.`teknisi_id` AS `teknisi_id`, `o`.`created_at` AS `created_at`, `o`.`updated_at` AS `updated_at`, `u`.`name` AS `teknisi_name`, group_concat(`oi`.`item_name` order by `oi`.`id` ASC separator ', ') AS `product_name`, coalesce(sum(`oi`.`quantity`),0) AS `total_quantity` FROM ((`orders` `o` left join `users` `u` on((`u`.`id` = `o`.`teknisi_id`))) left join `order_items` `oi` on((`oi`.`order_id` = `o`.`id`))) GROUP BY `o`.`id`, `o`.`customer_name`, `o`.`phone`, `o`.`address`, `o`.`payment_method`, `o`.`payment_status`, `o`.`order_status`, `o`.`total_price`, `o`.`teknisi_id`, `o`.`created_at`, `o`.`updated_at`, `u`.`name` ;

-- --------------------------------------------------------

--
-- Structure for view `v_orders_teknisi`
--
DROP TABLE IF EXISTS `v_orders_teknisi`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_orders_teknisi`  AS SELECT `o`.`id` AS `id`, `o`.`customer_name` AS `customer_name`, `o`.`phone` AS `phone`, `o`.`address` AS `address`, `o`.`order_status` AS `status`, `o`.`teknisi_id` AS `teknisi_id`, `o`.`created_at` AS `created_at`, group_concat(`oi`.`item_name` order by `oi`.`id` ASC separator ', ') AS `product_name` FROM (`orders` `o` left join `order_items` `oi` on((`oi`.`order_id` = `o`.`id`))) WHERE (`o`.`order_status` in ('pending','processing')) GROUP BY `o`.`id`, `o`.`customer_name`, `o`.`phone`, `o`.`address`, `o`.`order_status`, `o`.`teknisi_id`, `o`.`created_at` ;

